-- =====================================================
-- UPSERT NMO MEMBERS — incremental, preserves existing data
-- =====================================================
-- - INSERTs new handles
-- - On existing handles: only fills in display_name / avatar_url where
--   the current value is NULL (i.e. "update missing blocks" — never
--   overwrites real data you already have)
-- - Always bumps last_seen_at to mark the member as freshly observed
-- - level is NULL across this batch, so we coalesce with the existing
--   value to keep any levels you already captured
--
-- Run in Supabase SQL editor. Idempotent.
-- =====================================================

on conflict (handle) do update set
  display_name  = coalesce(public.nmo_members.display_name, excluded.display_name),
  avatar_url    = coalesce(public.nmo_members.avatar_url,    excluded.avatar_url),
  level         = coalesce(public.nmo_members.level,         excluded.level),
  last_seen_at  = now();

-- Sanity check
select
  count(*)                                            as total_members,
  count(display_name)                                 as with_name,
  count(avatar_url)                                   as with_avatar,
  count(level)                                        as with_level,
  count(*) filter (where last_seen_at > now() - interval '1 hour') as freshly_seen
from public.nmo_members;
